import {wrap,shadow,ref,text} from '../style.mjs';

// Redraw of an icon marked Needs work in the 2026-11-15 review (redraw round 2).
// The rejected recipe for this slug was in refreshments-12.mjs.
//
// This file is generated: the PAC_* path constants below were traced layer by flat colour
// from the label artwork printed flat on the six-pack carrier in the Target packshot
// (thresholded, outlines fitted with cubic Beziers), placed at their measured position on
// the bottle label and projected onto the bottle's cylinder, x = 100 + halfwidth *
// sin(u / radius), then injected here by a generator script. It is complete and
// self-contained; nothing is read at build time. Everything that is not a traced constant
// (bottle silhouette, label panel, bands, cap) is authored here from measurements of the
// front bottle in the same packshot.
const date='2026-11-16';

// Glass longneck bottles. Rendering copied from the Good beer bottles (`bottle()` in
// beer-expansion.mjs): glass gradient, clip, `glass` and `shade` overlays, the droplet
// speckle (drawn under the paper labels here, so it only shows on glass), a left specular and a faint right one, crown cap, base glint, shadow(47).
// Same height (cap at y=24, base at y=235) as those bottles. Each bottle supplies its own
// silhouette, measured off its packshot, and specular paths that follow it.
const drops=(x,y,w,h,n=18)=>Array.from({length:n},(_,i)=>`<ellipse cx="${x+(i*19)%w}" cy="${y+(i*31)%h}" rx="${i%3===0?1.2:.7}" ry="${i%3===0?1.8:1}" fill="#fff" opacity=".28"/>`).join('');
const CROWN='M87.5 24q12.5-4 25 0l2 6-3 2-3-1-3 1-3-1-3 1-3-1-3 1-3-1-3 1-2-2Z';
function bottle(slug,title,label,{shape,light,glass,dark,closure,spec,inside='',defs=''}){
  return wrap(slug,title,`${shadow(47)}<path d="${shape}" fill="${ref('liquid')}" stroke="${dark}" stroke-width=".65"/>
<g clip-path="${ref('bottleclip')}">${inside}${drops(72,67,56,156,25)}${label}<path d="${shape}" fill="${ref('glass')}" opacity=".4"/><path d="${shape}" fill="${ref('shade')}" opacity=".65"/>
<path d="${spec[0]}" fill="none" stroke="#fff9df" stroke-opacity=".24" stroke-width="2.8"/><path d="${spec[1]}" fill="none" stroke="#fff9df" stroke-opacity=".18" stroke-width="1.1"/></g>
${closure}<path d="M72 227q28 7 56 0" fill="none" stroke="#fff7d5" stroke-opacity=".3" stroke-width="1.2"/>`,
`<clipPath id="__ID__bottleclip"><path d="${shape}"/></clipPath><linearGradient id="__ID__liquid"><stop stop-color="${dark}"/><stop offset=".25" stop-color="${light}"/><stop offset=".58" stop-color="${glass}"/><stop offset="1" stop-color="${dark}"/></linearGradient>${defs}`);
}
// Traced constants are integers in 1/20 unit (keeps the exported file small).
const traced=(d,c,extra='')=>`<path transform="scale(.05)" d="${d}" fill="${c}" fill-rule="evenodd"${extra}/>`;
// Foil-paper fleck for the metallic gold labels: fixed pseudo-random dots (integer LCG).
function fleck(x0,y0,w,h,n,seed,light,dark){
  // x0,y0,w,h are whole units; every coordinate is an integer number of tenths.
  let v=seed;const d=['',''];
  const next=()=>(v=(v*73+41)%9973);
  for(let i=0;i<n;i++){const x=x0*10+next()%(w*10),y=y0*10+next()%(h*10),l=3+next()%5;d[i%2]+=`M${x/10} ${y/10}h${l/10}`;}
  return `<path d="${d[1]}" stroke="${light}" stroke-width=".7" stroke-linecap="round" opacity=".55"/><path d="${d[0]}" stroke="${dark}" stroke-width=".6" stroke-linecap="round" opacity=".32"/>`;
}

